// Copies the built reader page (reader-embed/dist) into assets/reader and
// writes the manifest Metro bundles it from: the page plus the fonts and wasm
// it loads by relative URL, each under the name the page asks for.
import {
	copyFileSync,
	mkdirSync,
	readdirSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const dist = join(root, "reader-embed", "dist");
const out = join(root, "assets", "reader");

rmSync(out, { recursive: true, force: true });
mkdirSync(out, { recursive: true });
const files = readdirSync(dist).filter((name) => name !== "index.html");
copyFileSync(join(dist, "index.html"), join(out, "reader.html"));
for (const name of files) copyFileSync(join(dist, name), join(out, name));

const entries = files
	.map(
		(name) =>
			`\t\t${JSON.stringify(name)}: require(${JSON.stringify(`./${name}`)}),`,
	)
	.join("\n");
writeFileSync(
	join(out, "manifest.js"),
	[
		"// Generated by scripts/reader-bundle.mjs.",
		"module.exports = {",
		'\tpage: require("./reader.html"),',
		"\tfiles: {",
		entries,
		"\t},",
		"};",
		"",
	].join("\n"),
);
console.log(`reader page + ${files.length} files → assets/reader`);
